      const full_name = frappe.session.user_fullname || "";
      frm.set_value('name_inspector', full_name);
      frm.refresh_field('name_inspector');
    }

    // เติมวันเวลาเริ่มต้นครั้งแรก
    if (!frm.doc.date_request_use) {
      frm.set_value('pm_date', frappe.datetime.get_today());
      frm.set_value('pm_time', frappe.datetime.now_time());
    }

    // เติมรายการตรวจเฉพาะตอนเอกสารใหม่ หรือเมื่อยังไม่มีแถว
    populate_table1_if_empty(frm);

    // ✅ ตั้ง query กรอง pm_device ตามแผนก
    set_pm_device_query(frm);
  },

  refresh(frm) {
    // ไม่ต้อง populate ซ้ำใน refresh เพื่อไม่ให้ค่าติ๊กถูกล้าง

    // ✅ กันลืม: refresh ทีไรก็ตั้ง query ให้ pm_device อีกรอบ
    set_pm_device_query(frm);
  },

  special(frm) {
    if (frm.doc.special === 0) {
      const full_name = frappe.session.user_fullname || "";
      frm.set_value('name_inspector', full_name);
      frm.refresh_field('name_inspector');
    }
  },

  // ✅ เมื่อเปลี่ยนแผนกให้ล้างค่า pm_device และตั้ง query ใหม่
  pm_department(frm) {
    // ถ้าเปลี่ยนแผนกแล้วเคยเลือกเครื่องไว้ ให้เคลียร์ก่อน
    if (frm.doc.pm_device) {
      frm.set_value('pm_device', null);
    }
    set_pm_device_query(frm);
  }
});

// ---------------- ฟังก์ชันกรอง pm_device ตามแผนก ----------------

function set_pm_device_query(frm) {
  frm.set_query('pm_device', function() {
    // ถ้าไม่ได้เลือกแผนก ยังไม่ต้องกรอง (แสดงทั้งหมด)
    if (!frm.doc.pm_department) {
      return {};
    }
    // กรองให้ Device Master.dm_department = pm_department ที่เลือก
    return {
      filters: {
        dm_department: frm.doc.pm_department   // 👈 ถ้า field จริงชื่ออื่นให้แก้ตรงนี้
      }
    };
  });
}

// ---------------- ฟังก์ชันเติมรายการ table1 ----------------

function populate_table1_if_empty(frm) {
  if (!frm.doc.table1 || frm.doc.table1.length === 0) {
    const cataract_list = [
      "สภาพภายนอก",
      "อุปกรณ์จับยึด",
      "ปลั๊กไฟ/สายไฟ/สายดิน",
      "ตรวจสอบสวิตซ์เปิด-ปิด",
      "หน้าจอแสดงผล",
      "ป้ายแสดงข้อมูลเครื่อง",
      "ความสะอาดของเครื่อง",
      "ทดสอบแบตเตอรี่",
      "เปิดหน้าจอแสดงผล",
      "การทำงานของปุ่มต่างๆ"
    ];

    cataract_list.forEach(text => {
      const row = frm.add_child('table1');
      row.pm_name = text;
      row.pm_chk = 1; // ✅ ติ๊กค่าเริ่มต้น
      // ถ้ามี pm_chk_wrong ให้แน่ใจว่าเริ่มต้นเป็น 0
      if (row.pm_chk_wrong == null) {
        row.pm_chk_wrong = 0;
      }
    });

    frm.refresh_field('table1');
  }
}

