/****************************************************
 * CCTV Preventive Maintenance – Client Script
 * - ตั้งชื่อผู้ตรวจ + วันที่/เวลาอัตโนมัติ
 * - ดึงรายการกล้องจาก CCTV Device Master มาใส่ table1
 * - cctv_on / cctv_off และ cctv_pb_on / cctv_pb_off
 *   เลือกได้ทีละ 1 ช่องในแต่ละแถว
 ****************************************************/

frappe.ui.form.on('CCTV Preventive Maintenance', {
    onload: async function (frm) {
        // ตั้งชื่อผู้ตรวจ ถ้าเป็นเอกสารใหม่ และยังไม่ได้ติ๊ก special
        if (frm.is_new() && !frm.doc.special) {
            frm.set_value('name_inspector', frappe.session.user_fullname || "");
            frm.refresh_field('name_inspector');
        }

        // ตั้งวันที่/เวลาเริ่มต้น ถ้ายังไม่มีค่า
        if (!frm.doc.cpm_date) {
            frm.set_value('cpm_date', frappe.datetime.get_today());
        }
        if (!frm.doc.cpm_time) {
            frm.set_value('cpm_time', frappe.datetime.now_time());
        }

        // เติมรายการกล้องครั้งแรกถ้า child table ยังว่าง
        if (!frm.doc.table1 || frm.doc.table1.length === 0) {
            const names = await get_cctv_names_from_master();
            fill_table_from_names(frm, names);
        }
    },

    // เปลี่ยน inspector อัตโนมัติเมื่อเอาติ๊ก special ออก
    special(frm) {
        if (frm.doc.special === 0) {
            frm.set_value('name_inspector', frappe.session.user_fullname || "");
            frm.refresh_field('name_inspector');
        }
    }
});

/* ===== Helpers ฝั่งฟอร์มหลัก ===== */

// ดึงชื่อกล้องจาก CCTV Device Master (เฉพาะ disable = 0)
async function get_cctv_names_from_master() {
    return new Promise((resolve) => {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'CCTV Device Master',
                fields: ['cctv_name'],
                filters: { 'disable': 0 },
                order_by: 'cctv_name asc',
                limit_page_length: 0
            },
            callback: function (r) {
                if (r.message && r.message.length > 0) {
                    const rows = r.message;
                    console.log(
                        `DEBUG: Rows returned via frappe.client.get_list: ${rows.length} items.`
                    );

                    // กรองชื่อซ้ำ
                    const seen = new Set();
                    const unique_names = (rows || [])
                        .map(x => (x.cctv_name || '').trim())
                        .filter(n => !!n && !seen.has(n) && seen.add(n));

                    console.log(
                        `DEBUG: Unique names ready to fill: ${unique_names.length} items.`
                    );
                    resolve(unique_names);
                } else {
                    frappe.msgprint(__('ไม่สามารถดึงรายการ CCTV จาก Master ได้ หรือดึงได้ไม่ครบ'));
                    resolve([]);
                }
            }
        });
    });
}

// เติมตาราง + default on / playback on
function fill_table_from_names(frm, names) {
    console.log(`DEBUG: fill_table_from_names adding ${names.length} rows.`);
    frm.clear_table('table1');

    (names || []).forEach(name => {
        const row = frm.add_child('table1');
        row.cctv_name = name;

        // ใช้ field name จริงใน child table
        if ('cctv_on' in row)  row.cctv_on  = 1;
        if ('cctv_off' in row) row.cctv_off = 0;

        if ('cctv_pb_on' in row)  row.cctv_pb_on  = 1;
        if ('cctv_pb_off' in row) row.cctv_pb_off = 0;
    });

    frm.refresh_field('table1');
}

/* ===== Exclusive checkboxes ใน Child Table ===== */

// helper สำหรับสลับคู่ checkbox ในแต่ละแถว
function toggle_pair_child(cdt, cdn, field, other_field) {
    let row = locals[cdt][cdn];
    if (!row) return;

    if (row[field]) {
        frappe.model.set_value(cdt, cdn, other_field, 0);
    }
}

// Child Doctype ของ table1: CCTV Preventive Maintenance Table
frappe.ui.form.on('CCTV Preventive Maintenance Table', {
    // ---- คู่ cctv_on / cctv_off ----
    cctv_on(frm, cdt, cdn) {
        toggle_pair_child(cdt, cdn, 'cctv_on', 'cctv_off');
    },
    cctv_off(frm, cdt, cdn) {
        toggle_pair_child(cdt, cdn, 'cctv_off', 'cctv_on');
    },

    // ---- คู่ cctv_pb_on / cctv_pb_off ----
    cctv_pb_on(frm, cdt, cdn) {
        toggle_pair_child(cdt, cdn, 'cctv_pb_on', 'cctv_pb_off');
    },
    cctv_pb_off(frm, cdt, cdn) {
        toggle_pair_child(cdt, cdn, 'cctv_pb_off', 'cctv_pb_on');
    }
});

