// Function กลางสำหรับรวมชื่อ
var generate_fullname = function(frm) {
    // ดึงค่าจาก field (ถ้าไม่มีให้เป็นค่าว่าง)
    let salutation = frm.doc.salutation || "";
    let namef = frm.doc.namef || "";
