    // รวมร่าง: คำนำหน้าชื่อ + ชื่อ + (เว้นวรรค) + นามสกุล
    // ใช้ .trim() เพื่อจัดการกรณีที่มีการเคาะสเปซเกิน
    let full = `${salutation}${namef} ${lastname}`.trim();

    // แสดงผลไปที่ช่อง fullname แบบ Real-time
    frm.set_value('fullname', full);
};


