                frappe.show_alert({
                    message: __('บันทึกการยืม OPD Card เรียบร้อยแล้ว'),
                    indicator: 'green'
                });
            });
        }
    },

    // --- เงื่อนไขฝั่ง "การคืน" ---
    officer_returning_opd_card: function(frm) {
        if (frm.doc.officer_returning_opd_card) {
            // ตั้งวันที่คืนปัจจุบัน
            frm.set_value('date_opd_card_returned', frappe.datetime.nowdate());

            // ดึงชื่อผู้รับคืน (คน Login) -> เปลี่ยนสถานะ -> บันทึกอัตโนมัติ
            get_user_info_and_set(frm, 'officer_returned_opd_card', true);
        }
    }
});

// ฟังก์ชันดึงชื่อ User จาก Server และจัดการการบันทึก
function get_user_info_and_set(frm, fieldname, is_returning = false) {
    frappe.call({
        method: 'frappe.client.get_value',
        args: {
            doctype: 'User',
            filters: { name: frappe.session.user },
            fieldname: 'full_name'
        },
        callback: function(r) {
            if (r.message && r.message.full_name) {
                const name = r.message.full_name;
                frm.set_value(fieldname, name);
                
                if (is_returning) {
                    frm.set_value('wf_opd_card_state', 'คืน OPD Card แล้ว');
                    frm.save().then(() => {
                        frappe.show_alert({
                            message: __(`รับคืน OPD Card เรียบร้อย`),
                            indicator: 'green'
                        });
                        frm.refresh();
                    });
                }
            }
        }
    });
}

