                    {
                        fieldname: 'pending_html',
                        fieldtype: 'HTML'
                    }
                ],
                primary_action_label: 'ปิดหน้าต่าง',
                primary_action() {
                    d.hide();
                }
            });

            // ปรับแต่งให้ Dialog แสดงผลเต็มหน้าจอ (Full Width)
            d.$wrapper.find('.modal-dialog').css({
