                            <td>${row.fullname || '-'}</td>
                            <td>${row.borrowing_officer || '-'}</td>
                            <td>${row.department || '-'}</td>
                            
                        </tr>
                    `;
                });
            } else {
                rows_html = `<tr><td colspan="6" class="text-center text-muted" style="padding: 20px;">🎉 ไม่พบข้อมูล OPD Card ที่ค้างการส่งคืนในระบบ</td></tr>`;
            }

            let html_content = `
                <div style="border: 1px solid #d1d8dd; border-radius: 8px; overflow: hidden; background: #fff;">
                    <div style="max-height: 70vh; overflow-y: auto;">
                        <table class="table table-hover table-striped" style="font-size: 14px; margin-bottom: 0;">
                            <thead>
                                <tr style="background-color: #f0f4f7; position: sticky; top: 0; z-index: 10;">
