                                    <th>แผนก</th>
                                    
                                </tr>
                            </thead>
                            <tbody>
                                ${rows_html}
                            </tbody>
                        </table>
                    </div>
                </div>
                <div style="margin-top: 15px; display: flex; justify-content: space-between; align-items: center;">
                    <p class="text-muted" style="margin:0;">* หมายเหตุ: คลิกที่แถวเพื่อเปิดดูเอกสาร</p>
                    <div style="font-size: 16px; font-weight: bold;">
                        รวมทั้งสิ้น: <span class="text-danger">${data.length}</span> รายการ
                    </div>
                </div>
            `;

            d.fields_dict.pending_html.$wrapper.html(html_content);
            d.show();
        }
    }
};
